import { Component, Input, Output, EventEmitter } from '@angular/core';

interface OtpSentPayload { channel: 'email' | 'sms'; }
interface LoginSucceededPayload { user_id: string; }
interface LoginFailedPayload { reason: 'invalid_otp' | 'expired' | 'locked' | 'network'; }

@Component({
  selector: 'app-login-screen',
  standalone: true,
  template: `
    <div class="login-screen" role="main" aria-labelledby="login-title">
      <h1 id="login-title">Login</h1>

      <div class="trace" aria-hidden="true">
        <span>identifier: {{ identifier }}</span>
        <span>prefill_identifier: {{ prefill_identifier }}</span>
      </div>

      <form *ngIf="!otpVisible" (submit)="onSubmitIdentifier($event)" novalidate>
        <label for="identifier-input">E-Mail oder Telefonnummer</label>
        <input
          id="identifier-input"
          type="text"
          [value]="identifier || prefill_identifier || ''"
          (input)="onIdentifierChange($any($event.target).value)"
          [attr.aria-invalid]="identifierError ? 'true' : 'false'"
          aria-describedby="identifier-help"
          [disabled]="locked"
        />
        <small id="identifier-help">Wir senden Ihnen einen 6-stelligen Code.</small>
        <button type="submit" [disabled]="locked">Code anfordern</button>
      </form>

      <form *ngIf="otpVisible" (submit)="onSubmitOtp($event)" novalidate>
        <label for="otp-input">6-stelliger Code</label>
        <input
          id="otp-input"
          type="text"
          inputmode="numeric"
          maxlength="6"
          autocomplete="one-time-code"
          [value]="otp"
          (input)="onOtpChange($any($event.target).value)"
          [attr.aria-invalid]="otpError ? 'true' : 'false'"
          aria-describedby="otp-help"
          [disabled]="locked"
        />
        <small id="otp-help">Gültig für 10 Minuten.</small>
        <div class="actions">
          <button type="submit" [disabled]="locked || otp.length !== 6">Bestätigen</button>
          <button type="button" (click)="onResend()" [disabled]="locked">Code erneut senden</button>
        </div>
        <p *ngIf="attempts > 0 && !locked" role="status" aria-live="polite">
          Fehlversuche: {{ attempts }} / 5
        </p>
        <p *ngIf="locked" role="alert">Konto für 15 Minuten gesperrt.</p>
      </form>
    </div>
  `,
  styles: [`
    .login-screen { max-width: 360px; margin: 2rem auto; font-family: system-ui, sans-serif; }
    .login-screen h1 { font-size: 1.5rem; margin-bottom: 1rem; }
    .login-screen label { display: block; margin-top: 0.75rem; font-weight: 600; }
    .login-screen input { width: 100%; padding: 0.5rem; font-size: 1rem; box-sizing: border-box; }
    .login-screen input[aria-invalid="true"] { border: 2px solid #b00020; }
    .login-screen button { margin-top: 0.75rem; padding: 0.5rem 1rem; font-size: 1rem; cursor: pointer; }
    .login-screen button:disabled { opacity: 0.5; cursor: not-allowed; }
    .login-screen .actions { display: flex; gap: 0.5rem; flex-wrap: wrap; }
    .login-screen .trace { display: none; }
    .login-screen small { color: #555; }
  `]
})
export class LoginScreenComponent {
  @Input() identifier: string = '';
  @Input() prefill_identifier?: string;

  @Output() otp_sent = new EventEmitter<OtpSentPayload>();
  @Output() otp_resent = new EventEmitter<void>();
  @Output() login_succeeded = new EventEmitter<LoginSucceededPayload>();
  @Output() login_failed = new EventEmitter<LoginFailedPayload>();

  otpVisible: boolean = false;
  otp: string = '';
  attempts: number = 0;
  locked: boolean = false;
  identifierError: boolean = false;
  otpError: boolean = false;
  otpIssuedAt: number = 0;

  private readonly MAX_ATTEMPTS = 5;
  private readonly LOCKOUT_MS = 15 * 60 * 1000;
  private readonly OTP_TTL_MS = 10 * 60 * 1000;

  onIdentifierChange(value: string): void {
    this.identifier = value;
    this.identifierError = false;
  }

  onOtpChange(value: string): void {
    this.otp = (value || '').replace(/\D/g, '').slice(0, 6);
    this.otpError = false;
  }

  onSubmitIdentifier(event: Event): void {
    event.preventDefault();
    if (this.locked) { return; }
    const value = this.identifier || this.prefill_identifier || '';
    const channel = this.detectChannel(value);
    if (!channel) {
      this.identifierError = true;
      return;
    }
    this.otpIssuedAt = Date.now();
    setTimeout(() => { this.otpVisible = true; }, 0);
    this.otp_sent.emit({ channel });
  }

  onSubmitOtp(event: Event): void {
    event.preventDefault();
    if (this.locked) {
      this.login_failed.emit({ reason: 'locked' });
      return;
    }
    if (Date.now() - this.otpIssuedAt > this.OTP_TTL_MS) {
      this.otpError = true;
      this.login_failed.emit({ reason: 'expired' });
      return;
    }
    if (this.otp.length !== 6) {
      this.otpError = true;
      this.login_failed.emit({ reason: 'invalid_otp' });
      this.registerFailedAttempt();
      return;
    }
    if (this.isValidOtp(this.otp)) {
      this.attempts = 0;
      this.login_succeeded.emit({ user_id: this.identifier });
    } else {
      this.otpError = true;
      this.login_failed.emit({ reason: 'invalid_otp' });
      this.registerFailedAttempt();
    }
  }

  onResend(): void {
    if (this.locked) { return; }
    this.otpIssuedAt = Date.now();
    this.otp = '';
    this.otpError = false;
    this.otp_resent.emit();
  }

  private registerFailedAttempt(): void {
    this.attempts++;
    if (this.attempts >= this.MAX_ATTEMPTS) {
      this.locked = true;
      this.login_failed.emit({ reason: 'locked' });
      setTimeout(() => {
        this.locked = false;
        this.attempts = 0;
      }, this.LOCKOUT_MS);
    }
  }

  private detectChannel(value: string): 'email' | 'sms' | null {
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) { return 'email'; }
    if (/^\+[1-9]\d{6,14}$/.test(value)) { return 'sms'; }
    return null;
  }

  private isValidOtp(otp: string): boolean {
    return /^\d{6}$/.test(otp);
  }
}
